fn divide(a: i32, b: i32) -> Option<i32> {
    if b == 0 { None } else { Some(a / b) }
}

fn divide_f64(a: f64, b: f64) -> f64 {
    a / b
}

fn modulo(a: i32, b: i32) -> i32 {
    a % b
}

fn modulo_generic<T: std::ops::Rem<Output=T>>(a: T, b: T) -> T {
    a % b
}

fn calc(a: f64, op: char, b: f64) -> Result<f64, String> {
    match op {
        '+' => Ok(a + b),
        '-' => Ok(a - b),
        '*' => Ok(a * b),
        '/' => if b != 0.0 { Ok(a / b) } else { Err("division by zero".into()) },
        _ => Err(format!("unknown op: {}", op)),
    }
}

fn power(base: i32, exp: u32) -> i32 {
    let mut result = 1;
    for _ in 0..exp {
        result *= base;
    }
    result
}

fn power_f64(base: f64, exp: f64) -> f64 {
    base.powf(exp)
}

fn abs_i32(n: i32) -> i32 {
    if n < 0 { -n } else { n }
}

fn abs_f64(n: f64) -> f64 {
    n.abs()
}

def divide(a, b):
    if b == 0:
        raise ValueError("division by zero")
    return a / b

def calc(a, op, b):
    ops = {'+': lambda: a + b, '-': lambda: a - b, '*': lambda: a * b, '/': lambda: a / b if b != 0 else None}
    return ops.get(op, lambda: None)()

fn binary_op<T, F>(a: T, b: T, f: F) -> T
where F: Fn(T, T) -> T {
    f(a, b)
}

// Usage: binary_op(3, 5, |a, b| a + b)  // 8
//        binary_op(3, 5, |a, b| a * b)  // 15

fn sum_list(nums: &[i32]) -> i32 {
    nums.iter().sum()
}

fn sum_fold(nums: &[i32]) -> i32 {
    nums.iter().fold(0, |acc, &x| acc + x)
}

fn average(nums: &[f64]) -> Option<f64> {
    if nums.is_empty() { return None; }
    Some(nums.iter().sum::<f64>() / nums.len() as f64)
}

fn min_val<T: PartialOrd>(a: T, b: T) -> T {
    if a <= b { a } else { b }
}

fn max_val<T: PartialOrd>(a: T, b: T) -> T {
    if a >= b { a } else { b }
}

fn clamp(val: i32, min: i32, max: i32) -> i32 {
    if val < min { min } else if val > max { max } else { val }
}

fn add_floats(a: f64, b: f64) -> f64 {
    a + b
}

fn safe_add(a: i32, b: i32) -> Option<i32> {
    a.checked_add(b)
}

fn safe_mul(a: i32, b: i32) -> Option<i32> {
    a.checked_mul(b)
}
